package com.bank.hierarchy;

import java.util.logging.*;

public class StaticInheritanceDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Touching SavingsAccount triggers class loading:
        // parent Account static block runs FIRST, then SavingsAccount.
        SavingsAccount savings = new SavingsAccount();

        // Static VARIABLE hiding: resolved by the REFERENCE type, not the object.
        Account asBase = savings;                 // same object, base-typed reference
        log.info(() -> "asBase.CATEGORY   = " + Account.CATEGORY);        // GENERIC
        log.info(() -> "SavingsAccount.CATEGORY = " + SavingsAccount.CATEGORY); // SAVINGS

        // Static METHOD hiding: resolved by declared type, NOT dynamic dispatch.
        log.info(() -> "Account.accountType()        = " + Account.accountType());        // BASE
        log.info(() -> "SavingsAccount.accountType()  = " + SavingsAccount.accountType()); // SAVINGS

        // super.accountType() would NOT compile — static methods have no super dispatch.
    }
}

// ─── Would be Account.java in a real project ───
class Account {
    static final String CATEGORY = "GENERIC";   // static field (will be hidden)
    private static final Logger log = Logger.getLogger("BankLog");
    static { log.info("Static block: Account loaded (parent first)"); }

    static String accountType() { return "BASE"; } // static method (will be hidden)
}

// ─── Would be SavingsAccount.java in a real project ───
class SavingsAccount extends Account {
    static final String CATEGORY = "SAVINGS";    // HIDES Account.CATEGORY
    private static final Logger log = Logger.getLogger("BankLog");
    static { log.info("Static block: SavingsAccount loaded (child second)"); }

    // HIDES Account.accountType(); @Override here would be a COMPILE ERROR.
    static String accountType() { return "SAVINGS"; }
}
